def func(lists, k):
  # Initialize a heap queue to store the top k elements
  heap = []
  # Loop through the lists and find the top k elements
  for list in lists:
      for element in list:
          # Check if the element is already in the heap
          if element in heap:
              # Increment the count of the element
              heap[heap.index(element)] += 1
          else:
              # Add the element to the heap
              heapq.heappush(heap, (element, 1))
              # Check if the heap size is greater than k
              if len(heap) > k:
                  # Remove the smallest element from the heap
                  heapq.heappop(heap)
  # Return the top k elements
  return [element for element, count in heap]

def func(lists, k):
  from heapq import heapify, heappop, heappush

  # Initialize the heap with the first element of each list
  heap = [list[0] for list in lists]

  # Build the heap
  heapify(heap)

  # Iterate through the lists and extract the top k elements
  for list in lists:
      for i in range(1, k):
          if i < len(list):
              heappush(heap, list[i])
          else:
              break

  # Return the top k elements
  return heap

