def top_k_frequent_integers(lists, k):
  """
  Returns the top k integers that occur most frequently from given lists of sorted and distinct integers using heap queue algorithm.
  """
  # Initialize a dictionary to store the count of each integer
  counts = {}
  for lst in lists:
      for num in lst:
          if num in counts:
              counts[num] += 1
          else:
              counts[num] = 1

  # Initialize a min heap to store the top k frequent integers
  heap = []

  # Iterate over the counts dictionary and add the top k frequent integers to the heap
  for num, count in counts.items():
      heappush(heap, (count, num))
      if len(heap) > k:
          heappop(heap)

  # Return the top k frequent integers in the heap
  return [num for count, num in heap]

