def func(lists, k):
  import heapq

  # Initialize the heap with the first element of each list
  heap = [list[0] for list in lists]

  # Loop through the rest of the elements of each list
  for list in lists:
      for element in list[1:]:
          # If the element is already in the heap, remove it and add the new element
          if element in heap:
              heapq.heappop(heap)
              heapq.heappush(heap, element)
          # If the heap size is smaller than k, add the new element
          elif len(heap) < k:
              heapq.heappush(heap, element)

  # Return the top k elements of the heap
  return heapq.nlargest(k, heap)

