import itertools

def groupby(iterable, key=None):
    if key is None:
        key = lambda x: x
    it = iter(iterable)
    _key = next(it)
    group = [key(_key)]
    for elem in it:
        if key(elem) != _key:
            yield group
            group = [key(elem)]
        else:
            group.append(elem)
    yield group

def encode_list(my_list):
    for key, group in groupby(my_list):
        yield [len(group), key]
