def find_longest_repeating_subseq(s):
  """
  Find the length of the longest repeating subsequence in the string s
  such that the two subsequences don't have same string characters at same positions.
  """
  longest = 0
  for i in range(len(s)):
      for j in range(i+1, len(s)):
          if s[i] != s[j]:
              longest = max(longest, j - i)
  return longest

