  """
  Find the longest repeating subsequence in a given string such that
  the two subsequences don't have same string characters at same positions.
  """
  longest_subseq = 0
  for i in range(len(s)):
      for j in range(i+1, len(s)):
          if s[i] != s[j]:
              subseq = 1
              for k in range(i+1, j):
                  if s[k] == s[j]:
