def max_sub_array_sum_repeated(arr, k, n):
  """
  Find the largest sum of contiguous array in the modified array which is formed by repeating the given array k times.
  """
  # Initialize variables
  max_sum = 0
  curr_sum = 0
  repeated_arr = [0] * (n * k)

  # Copy the input array into the repeated array
  for i in range(n):
      for j in range(k):
          repeated_arr[i + j * n] = arr[i]

  # Calculate the sum of the repeated array
  for i in range(n * k):
      curr_sum += repeated_arr[i]
      if curr_sum > max_sum:
          max_sum = curr_sum
      elif curr_sum < 0:
          curr_sum = 0

  return max_sum

def max_sub_array_sum_repeated(arr, k, n):
  # Initialize variables
  max_sum = 0
  current_sum = 0
  repeated_arr = [arr[i] for i in range(len(arr)) for _ in range(k)]

  # Iterate through the repeated array
  for i in range(len(repeated_arr)):
      current_sum += repeated_arr[i]
      if i > n - 1:
          current_sum -= repeated_arr[i - n]
      if current_sum > max_sum:
          max_sum = current_sum

  return max_sum

