def find_last_occurrence(arr, target):
  """
  Find the index of the last occurrence of a given number in a sorted array.
  """
  low = 0
  high = len(arr) - 1

  while low <= high:
      mid = (low + high) // 2
      if arr[mid] == target:
          high = mid - 1
      else:
          low = mid + 1

  if low < len(arr) and arr[low] == target:
      return low
  else:
      return -1

