def find_demlo(number):
  """
  Returns the Demlo number for the given number.
  """
  demlo_number = ''
  for i in range(len(number)):
      if i % 2 == 0:
          demlo_number += str(int(number[i]) + 1)
      else:
          demlo_number += str(int(number[i]) - 1)
  return demlo_number

