def find_minimum_range(arr):
  """
  Find the smallest range that includes at-least one element from each of the given arrays.
  :param arr: a list of arrays
  :return: a tuple of the smallest range
  """
  min_val = float('inf')
  max_val = float('-inf')
  for i in range(len(arr)):
      for j in range(len(arr[i])):
          if arr[i][j] < min_val:
              min_val = arr[i][j]
          if arr[i][j] > max_val:
              max_val = arr[i][j]
  return (min_val, max_val)

def find_minimum_range(arrays):
  """
