def minimum_Length(s):
  # create a dictionary to keep track of the characters and their counts
  char_count = {}
  for char in s:
      if char in char_count:
          char_count[char] += 1
      else:
          char_count[char] = 1

  # find the character with the minimum count
  min_count = min(char_count.values())
  min_char = None
  for char, count in char_count.items():
      if count == min_count:
          min_char = char
          break

  # remove the minimum occurrence of the character
  return s.replace(min_char, "", min_count)

