def calculate_polygons(num_polygons, num_sides, side_length, angle_between_sides, rotation_angle):
  polygons = []
  for i in range(num_polygons):
      polygon = []
      for j in range(num_sides):
          x = side_length * math.cos(2 * math.pi * j / num_sides + rotation_angle)
          y = side_length * math.sin(2 * math.pi * j / num_sides + rotation_angle)
          polygon.append((x, y))
      polygons.append(polygon)
  return polygons

